//! Semantic-parity gate: the hand-ported parser must produce the same
//! `Block`/`Span` tree as `Ipe.Markdown` over the shared corpus.
//!
//! The expected trees are NOT hand-authored: they are snapshotted from an `ipe`
//! run of `examples/shapes/script/markdown-parity` (the `Ipe.Markdown`
//! serializer), regenerated by `tools/scripts/regen-markdown-parity.sh` and
//! committed as `snapshot.txt`. This standing test re-parses each corpus source
//! with the port and asserts its canonical S-expression equals the snapshot's —
//! so `Ipe.Markdown` stays the single source of truth and any drift (in the port
//! OR in `Ipe.Markdown` without regeneration) reddens the build.

/// The committed snapshot produced by an `ipe` run of the parity serializer.
pub const SNAPSHOT: &str = include_str!("parity/snapshot.txt");

/// The parse a corpus entry pins, with its expected canonical S-expression.
#[derive(Debug)]
pub enum Expected {
    /// A whole document through `parseBlocks`.
    Blocks(String),
    /// One line of inline markup through `parseSpans`.
    Spans(String),
}

/// One corpus entry parsed out of the snapshot: name, raw Markdown source, and
/// the expected tree.
#[derive(Debug)]
pub struct Entry {
    pub name: String,
    pub source: String,
    pub expected: Expected,
}

/// The marker that closes a source section and opens a block tree.
const BLOCKS_MARKER: &str = "--- blocks ---";
/// The marker that closes a source section and opens a span list.
const SPANS_MARKER: &str = "--- spans ---";
/// The marker that closes a frame.
const END_MARKER: &str = "--- end ---";

/// Parse the framed snapshot into its entries.
///
/// Each frame is:
/// ```text
/// === <name> ===
/// --- source ---
/// <source, possibly multi-line>
/// --- blocks ---            (or `--- spans ---`)
/// <sexpr, possibly multi-line>
/// --- end ---
/// ```
#[must_use]
pub fn parse_snapshot(text: &str) -> Vec<Entry> {
    let mut entries = Vec::new();
    let lines: Vec<&str> = text.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let Some(line) = lines.get(i) else { break };
        let Some(name) = line
            .strip_prefix("=== ")
            .and_then(|s| s.strip_suffix(" ==="))
        else {
            i += 1;
            continue;
        };
        // Expect the fixed section markers; collect until the next marker.
        i += 1;
        if lines.get(i).copied() != Some("--- source ---") {
            continue;
        }
        i += 1;
        let (source, marker) = collect_until(&lines, &mut i, &[BLOCKS_MARKER, SPANS_MARKER]);
        let (tree, _) = collect_until(&lines, &mut i, &[END_MARKER]);
        let expected = if marker == Some(SPANS_MARKER) {
            Expected::Spans(tree)
        } else {
            Expected::Blocks(tree)
        };
        entries.push(Entry {
            name: name.to_owned(),
            source,
            expected,
        });
    }
    entries
}

/// Collect lines from `*i` up to (not including) the first line equal to one
/// of `markers`, advancing `*i` past it.
///
/// Joins with `\n`; also returns the marker met (`None` at end of input).
fn collect_until<'m>(
    lines: &[&str],
    i: &mut usize,
    markers: &[&'m str],
) -> (String, Option<&'m str>) {
    let mut collected: Vec<&str> = Vec::new();
    let mut met = None;
    while let Some(&line) = lines.get(*i) {
        *i += 1;
        if let Some(marker) = markers.iter().find(|m| **m == line) {
            met = Some(*marker);
            break;
        }
        collected.push(line);
    }
    (collected.join("\n"), met)
}

#[cfg(test)]
mod tests {
    use super::super::MAX_BLOCKQUOTE_DEPTH;
    use super::super::parse::{parse_blocks, parse_spans};
    use super::super::sexpr::{blocks_to_sexpr, spans_to_sexpr};
    use super::{Expected, SNAPSHOT, parse_snapshot};

    /// The `Ipe.Markdown` source, read for its quote-depth ceiling.
    const IPE_MARKDOWN: &str = include_str!("../../../stdlib/Ipe/Markdown.ipe");

    #[test]
    fn snapshot_is_non_empty() {
        let entries = parse_snapshot(SNAPSHOT);
        assert!(
            entries.len() >= 20,
            "parity corpus shrank unexpectedly: {} entries",
            entries.len()
        );
    }

    /// The port's tree equals `Ipe.Markdown`'s tree for every corpus document.
    /// A divergence here means the hand-port drifted from the SSOT parser (or
    /// the snapshot was regenerated after an `Ipe.Markdown` change and the port
    /// was not updated to match) — either way the parse SSOT is broken.
    #[test]
    fn port_matches_ipe_markdown_snapshot() {
        for entry in parse_snapshot(SNAPSHOT) {
            let (got, want) = match &entry.expected {
                Expected::Blocks(want) => (blocks_to_sexpr(&parse_blocks(&entry.source)), want),
                Expected::Spans(want) => (spans_to_sexpr(&parse_spans(&entry.source)), want),
            };
            assert_eq!(
                &got, want,
                "parity drift on `{}`\n  source: {:?}\n  expected (Ipe.Markdown):\n{}\n  got (port):\n{}",
                entry.name, entry.source, want, got
            );
        }
    }

    /// The port's quote ceiling is the `Ipe.Markdown` `maxQuoteDepth` value.
    ///
    /// The source must define it on exactly one `maxQuoteDepth = <digits>`
    /// line, so a second definition or a computed value cannot slip past.
    #[test]
    fn quote_ceiling_is_one_constant() {
        let values: Vec<&str> = IPE_MARKDOWN
            .lines()
            .filter_map(|l| l.strip_prefix("maxQuoteDepth = "))
            .collect();
        assert_eq!(
            values.len(),
            1,
            "Ipe.Markdown must define maxQuoteDepth on exactly one line: {values:?}"
        );
        let digits = values.first().copied().unwrap_or_default().trim_end();
        assert!(
            !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()),
            "maxQuoteDepth must be a literal: {digits:?}"
        );
        assert_eq!(digits.parse::<usize>().ok(), Some(MAX_BLOCKQUOTE_DEPTH));
    }
}
